/bin/bash -lc "python - <<'PY'
import csv, json, math
from collections import defaultdict
VALUE_EPS=1e-8

def read_csv(path):
    with open(path,newline='') as f:
        return list(csv.DictReader(f))

def to_float(v):
    return float(v) if v not in ('',None) else 0.0

base='/app/data'
state=json.load(open('/app/state/week2_state.json'))
current=json.load(open(base+'/current_week.json'))
weeks=[int(r['week']) for r in read_csv(base+'/weeks.csv') if int(r['week'])>=current['week']]
products={r['product_id']:r for r in read_csv(base+'/products.csv')}
materials={r['material_id']:r for r in read_csv(base+'/materials.csv')}
plants={r['plant_id']:r for r in read_csv(base+'/plants.csv')}
plant_products={(r['plant_id'],r['product_id']):{k:to_float(r[k]) if k not in ('plant_id','product_id') else r[k] for k in r} for r in read_csv(base+'/plant_products.csv')}
bom={(r['product_id'],r['material_id']):to_float(r['tons_material_per_ton_product']) for r in read_csv(base+'/bom.csv')}
warehouses={r['dc_id']:r for r in read_csv(base+'/warehouses.csv')}
customers={r['customer_id']:r for r in read_csv(base+'/customers.csv')}
demand=defaultdict(float)
for r in read_csv(base+'/demand.csv'): demand[(int(r['week']),r['customer_id'],r['product_id'])]=to_float(r['demand_tons'])
plant_to_dc={(r['plant_id'],r['dc_id']):{ 'capacity':to_float(r['weekly_capacity_tons'])} for r in read_csv(base+'/plant_to_dc_lanes.csv')}
dc_to_customer={(r['dc_id'],r['customer_id']):{'capacity':to_float(r['weekly_capacity_tons'])} for r in read_csv(base+'/dc_to_customer_lanes.csv')}
dc_transfer={(r['from_dc'],r['to_dc']):{'capacity':to_float(r['weekly_capacity_tons'])} for r in read_csv(base+'/dc_transfer_lanes.csv')}
policy=read_csv(base+'/planning_policies.csv')[0]
material_discount=to_float(policy['material_robust_discount'])
material_supply={(int(r['week']),r['plant_id'],r['material_id']):{'regular':to_float(r['regular_available_tons']),'emcap':to_float(r['emergency_cap_tons'])} for r in read_csv(base+'/material_supply.csv')}
safety=defaultdict(float)
for r in read_csv(base+'/safety_stock.csv'): safety[(r['dc_id'],r['product_id'])]=to_float(r['safety_stock_tons'])
pipeline_prod=defaultdict(float); pipeline_mat=defaultdict(float)
for r in read_csv(base+'/pipeline_receipts.csv'):
    if r['receipt_type']=='product': pipeline_prod[(int(r['week']),r['to'],r['item'])]+=to_float(r['quantity'])
    else: pipeline_mat[(int(r['week']),r['to'],r['item'])]+=to_float(r['quantity'])
customers_by_region=defaultdict(list)
for c,a in customers.items(): customers_by_region[a['region']].append(c)
next_week={weeks[i]:weeks[i+1] if i+1<len(weeks) else None for i in range(len(weeks))}
reserve=defaultdict(float)
for w in weeks:
    nw=next_week[w]
    for dc,wa in warehouses.items():
        for p in products:
            reserve[(w,dc,p)] = 0 if nw is None else to_float(policy['reserve_multiplier_next_week_demand'])*sum(demand[(nw,c,p)] for c in customers_by_region[wa['region']])

plan_rows=[r for r in csv.DictReader(open('/app/submissions/initial_plan.csv')) if int(r['week'])>=2]
vals=defaultdict(float)
for r in plan_rows:
    key=(r['variable'],int(r['week']),r['item'],r['from'],r['to'])
    vals[key]+=float(r['quantity'])

viol=[]
# dictionaries
setup=defaultdict(float); preg=defaultdict(float); pot=defaultdict(float); spd=defaultdict(float); sdc=defaultdict(float); tr=defaultdict(float); inv=defaultdict(float); sho=defaultdict(float); em=defaultdict(float)
for (var,w,item,fr,to),q in vals.items():
    if var=='setup': setup[(w,fr,item)]=q
    elif var=='produce_regular': preg[(w,fr,item)]=q
    elif var=='produce_overtime': pot[(w,fr,item)]=q
    elif var=='ship_plant_dc': spd[(w,fr,to,item)]=q
    elif var=='ship_dc_customer': sdc[(w,fr,to,item)]=q
    elif var=='transfer_dc': tr[(w,fr,to,item)]=q
    elif var=='inventory': inv[(w,fr,item)]=q
    elif var=='shortage': sho[(w,fr,item)]=q
    elif var=='emergency_material': em[(w,to,item)]=q

for w in weeks:
  for (plant,p),attrs in plant_products.items():
    total=preg[(w,plant,p)] + pot[(w,plant,p)]
    y=setup[(w,plant,p)]
    if total > float(attrs['max_weekly_tons']) * y + 1e-6: viol.append(('max_run',w,plant,p,total,float(attrs['max_weekly_tons'])*y))
    if total +1e-6 < float(attrs['min_run_tons']) * y: viol.append(('min_run',w,plant,p,total,float(attrs['min_run_tons'])*y))
  for plant in plants:
    reg=sum(preg[(w,plant,p)]/float(plant_products[(plant,p)]['tons_per_hour']) for p in products if (plant,p) in plant_products)
    if reg > to_float(plants[plant]['regular_hours'])+1e-6: viol.append(('reghrs',w,plant,reg,to_float(plants[plant]['regular_hours'])))
    ot=sum(pot[(w,plant,p)]/float(plant_products[(plant,p)]['tons_per_hour']) for p in products if (plant,p) in plant_products)
    if ot > to_float(plants[plant]['overtime_hours'])+1e-6: viol.append(('othrs',w,plant,ot,to_float(plants[plant]['overtime_hours'])))
    st=sum(float(plant_products[(plant,p)]['setup_hours'])*setup[(w,plant,p)] for p in products if (plant,p) in plant_products)
    if st > to_float(plants[plant]['weekly_setup_team_hours'])+1e-6: viol.append(('setuphrs',w,plant,st,to_float(plants[plant]['weekly_setup_team_hours'])))
    for m in materials:
      use=sum(bom.get((p,m),0.0)*(preg[(w,plant,p)] + pot[(w,plant,p)]) for p in products if (plant,p) in plant_products)
      rhs=material_discount*material_supply[(w,plant,m)]['regular'] + pipeline_mat[(w,plant,m)] + em[(w,plant,m)]
      if use > rhs + 1e-6: viol.append(('material',w,plant,m,use,rhs))
      if em[(w,plant,m)] > material_supply[(w,plant,m)]['emcap'] + 1e-6: viol.append(('emcap',w,plant,m,em[(w,plant,m)],material_supply[(w,plant,m)]['emcap']))
  for (plant,dc),a in plant_to_dc.items():
    tot=sum(spd[(w,plant,dc,p)] for p in products)
    if tot > a['capacity']+1e-6: viol.append(('pdcap',w,plant,dc,tot,a['capacity']))
  for (dc,c),a in dc_to_customer.items():
    tot=sum(sdc[(w,dc,c,p)] for p in products)
    if tot > a['capacity']+1e-6: viol.append(('dccap',w,dc,c,tot,a['capacity']))
  for (d1,d2),a in dc_transfer.items():
    tot=sum(tr[(w,d1,d2,p)] for p in products)
    if tot > a['capacity']+1e-6: viol.append(('trcap',w,d1,d2,tot,a['capacity']))
  for c in customers:
    for p in products:
      dem=demand[(w,c,p)]
      if dem<=0: continue
      shipped=sum(sdc[(w,dc,c,p)] for dc in warehouses if (dc,c) in dc_to_customer)
      if abs(shipped+sho[(w,c,p)]-dem)>1e-6: viol.append(('demand',w,c,p,shipped+sho[(w,c,p)],dem))
      if shipped +1e-6 < to_float(customers[c]['min_service_rate']) * dem: viol.append(('service',w,c,p,shipped,to_float(customers[c]['min_service_rate'])*dem))
  for (plant,p) in plant_products:
    shipped=sum(spd[(w,plant,dc,p)] for dc in warehouses if (plant,dc) in plant_to_dc)
    prod=preg[(w,plant,p)] + pot[(w,plant,p)]
    if abs(shipped-prod)>1e-6: viol.append(('plantbal',w,plant,p,shipped,prod))
  prevw = None if w==weeks[0] else weeks[weeks.index(w)-1]
  for dc in warehouses:
    totalinv=sum(inv[(w,dc,p)] for p in products)
